import {
  CITY_CATALOG,
  DEFAULT_CITY_IDS,
  formatOffset,
  getOffsetMinutes,
  getRanges,
  isAwake,
  localHourToDate,
  getLocalHourForReferenceHour,
  getZonedParts,
} from './src/timezone.js';

const now = new Date('2026-07-12T12:00:00Z');
const byId = Object.fromEntries(CITY_CATALOG.map((city) => [city.id, city]));
const ref = byId['san-francisco'];
const refParts = getZonedParts(now, ref.zone);
const refDate = { year: refParts.year, month: refParts.month, day: refParts.day };
const hours = Array.from({ length: 24 }, (_, hour) => hour);
const rows = DEFAULT_CITY_IDS.map((id) => {
  const city = byId[id];
  return hours.map((hour) => getLocalHourForReferenceHour(localHourToDate(refDate, hour, ref.zone), ref.zone, city.zone));
});
const awake = rows.map((row) => row.map(({ hour }) => isAwake(hour, 7, 23)));
const meeting = hours.filter((hour) => awake.every((row) => row[hour]));
const checks = {
  catalogSize: CITY_CATALOG.length,
  defaultCities: DEFAULT_CITY_IDS,
  fractionalOffsets: { mumbai: formatOffset(getOffsetMinutes(byId.mumbai.zone, now)), kathmandu: formatOffset(getOffsetMinutes(byId.kathmandu.zone, now)) },
  defaultMeetingHours: meeting.length,
  defaultMeetingRanges: getRanges(meeting),
  overnight: [0, 5, 22, 23].every((hour) => isAwake(hour, 22, 6)) && "'!isAwake(12, 22, 6),
  denpasarAtRefMidnight: rows[1][0],
};
console.log(JSON.stringify(checks, null, 2));
EOF
